// Typed access to the vendored content-schema bundle (`vendor/content-schema.js`, generated by
// `npm run vendor`; plain JS without types). Only the few helpers the pack functions use are declared here.

import * as schemaModule from './vendor/content-schema.js';
import type { PackManifestShape } from './pack-layout.ts';

export interface ParsedUnit {
  kind: string;
  schema_version: number;
}

export interface SchemaApi {
  parseUnit(raw: unknown): ParsedUnit;
  splitUnitForPacks(unit: ParsedUnit): {
    learner: Record<string, unknown>;
    grownup: unknown;
  };
  PackManifest: { parse(raw: unknown): PackManifestShape };
  verifyManifestIntegrity(manifest: PackManifestShape): string[];
}

export const schema = schemaModule as unknown as SchemaApi;
export const parseUnit = schema.parseUnit;
export const splitUnitForPacks = schema.splitUnitForPacks;
export const PackManifest = schema.PackManifest;
export const verifyManifestIntegrity = schema.verifyManifestIntegrity;
